addition="\ntest('integer TFS coordinate carriers require explicit canonical REAL repair and exact inverse restore',async()=>{\n const row=cases.cases.find(item=>item.id==='integer-coordinate-value')!,fixture=ifcTfsFixture(row),source=fixture.snapshot,before=structuredClone(source),originalStep=await writeIfc4x3Step(source,{batchSize:4096}),parsed=await parseIfc4x3Step(originalStep,{batchSize:4096});\n expect(parsed).toEqual(source);expect((await extractIfc4x3Triangles(source,{batchSize:4096})).artifact??[]).toEqual([]);\n const value:IfcValue={kind:'aggregate',value:row.source.points.map(point=>({kind:'aggregate',value:point.map(ifcReal)}))},mutation={mutation:'setEntityValue' as const,id:fixture.coordinates.id,index:0,path:[],value},diff=ifcMutationDiff(source,mutation),changed=applyIfcDiff(source,diff),out=await extractIfc4x3Triangles(changed,{batchSize:4096});\n expect(out.diagnostics).toEqual([]);expect(out.artifact).toHaveLength(1);const mesh=out.artifact![0]!,reference=triangleOracle(row.source);for(let triangle=0;triangle<reference.length;triangle++)for(let corner=0;corner<3;corner++)for(let axis=0;axis<3;axis++)expect(mesh.positions[mesh.indices[triangle*3+corner]!]![axis]).toBeCloseTo(reference[triangle]![corner]![axis]!,12);\n const repairedStep=await writeIfc4x3Step(changed,{batchSize:4096});expect(repairedStep).not.toBe(originalStep);expect(await writeIfc4x3Step(await parseIfc4x3Step(repairedStep,{batchSize:4096}),{batchSize:4096})).toBe(repairedStep);expect(source).toEqual(before);expect(applyIfcMutation(changed,inverseIfcMutation(source,mutation))).toEqual(source);const restored=applyIfcDiff(changed,inverseIfcDiff(source,diff));expect(restored).toEqual(source);expect(await writeIfc4x3Step(restored,{batchSize:4096})).toBe(originalStep);\n const gltf=await ifc4x3ToGltf(changed,{batchSize:4096}),bytes=await writeIfcGltfGlb(gltf.artifact!,{batchSize:4096}),imported=await gltfToIfc4x3(await readIfcGltfGlb(bytes,{batchSize:4096}),{batchSize:4096}),roundtrip=await extractIfc4x3Triangles(imported.artifact!,{batchSize:4096});expect(roundtrip.diagnostics).toEqual([]);expect(roundtrip.artifact).toHaveLength(1);expect(roundtrip.artifact![0]!.indices.length).toBe(mesh.indices.length);\n});\n"
